'use strict';
const VERSION=1, KEY='royz-artist-room-v1';
const QUESTIONS=QUIZ.sections.flatMap((s,si)=>s.questions.map(q=>({...q,section:si})));
const SCORED=QUESTIONS.filter(q=>q.options?.some(o=>o.scores));
const main=document.getElementById('main');
let state={version:VERSION,answers:{},notes:{},index:0,view:'intro',lens:'artist',ratings:{}},storageOK=true,presentIndex=0;
const audioURLs={},audioNames={};
try{const saved=localStorage.getItem(KEY);if(saved)state=cleanState(JSON.parse(saved));}catch(e){storageOK=false;}
function cleanState(x){if(!x||x.version!==VERSION||!x.answers||typeof x.answers!=='object')throw Error('Use a Royz v1 backup file.');const answers={};for(const q of QUESTIONS){const a=x.answers[q.id];if(q.type==='text'){if(typeof a==='string')answers[q.id]=a.slice(0,5000);}else if(a==='__unsure')answers[q.id]=a;else if(q.type==='multi'&&Array.isArray(a)){answers[q.id]=[...new Set(a.filter(v=>q.options.some(o=>o.value===v)))];}else if(q.options?.some(o=>o.value===a))answers[q.id]=a;}const ratings={};for(const k of ['identity','emotion','artifacts','repeatable'])if(Number.isInteger(Number(x.ratings?.[k]))&&Number(x.ratings[k])>=1&&Number(x.ratings[k])<=5)ratings[k]=String(x.ratings[k]);const notes={};for(const q of QUESTIONS)if(typeof x.notes?.[q.id]==='string')notes[q.id]=x.notes[q.id].slice(0,5000);return{version:VERSION,answers,notes,index:Math.min(QUESTIONS.length-1,Math.max(0,Math.floor(Number(x.index))||0)),view:['intro','quiz','review','report'].includes(x.view)?x.view:'intro',lens:x.lens==='label'?'label':'artist',ratings};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ans=id=>state.answers[id];
const label=id=>{const q=QUESTIONS.find(q=>q.id===id);const a=ans(id);if(a==='__unsure')return 'Still exploring';if(Array.isArray(a))return a.map(v=>q.options.find(o=>o.value===v)?.label).filter(Boolean).join('; ');return q?.options?.find(o=>o.value===a)?.label||a||'Not answered yet';};
const answered=q=>q.type==='text'?Boolean(ans(q.id)?.trim()):Array.isArray(ans(q.id))?ans(q.id).length>0:Boolean(ans(q.id));
const count=()=>QUESTIONS.filter(answered).length;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}document.getElementById('save-status').textContent=storageOK?'Saved on this browser':'Storage unavailable · save a backup';}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4000);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportJSON(){download('ROYZ-artist-answers.json',JSON.stringify({...state,exportedAt:new Date().toISOString(),questionnaireVersion:QUIZ.version,answerLabels:Object.fromEntries(QUESTIONS.map(q=>[q.id,label(q.id)])),preferenceResult:score()},null,2),'application/json');toast('Backup downloaded. Bring this file back for your bespoke campaign.');}
function go(view,index){state.view=view;if(index!==undefined)state.index=index;persist();render();window.scrollTo(0,0);main.focus({preventScroll:true});}
function render(){document.body.classList.remove('present');main.innerHTML=state.view==='quiz'?quizHTML():state.view==='review'?reviewHTML():state.view==='report'?reportHTML():introHTML();bind();if(state.view==='report')updateLab();}
function introHTML(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Private session / Royz · September 2026</span><h1>You’re the artist.<br>You’re the label.<br><span class="serif">Let’s find<br>your world.</span></h1><p class="hero-sub">An artist-development session made for Ian.</p><p>Your taste. Your voice. Your point of view. Turn those into a sound you can stand behind and a first chapter worth releasing.</p><div class="actions"><button class="primary" data-action="start">${count()?'Continue your session':'Enter the room'} <span>↗</span></button><button class="textbtn" data-action="import">Load a saved session</button></div><span class="micro">42 questions · about 20–30 minutes · pause whenever</span></div><div class="portrait"><img src="assets/royz-night.jpg" alt="Ian in a jacket and tie, photographed in dramatic low light"><div class="credit micro"><span>ARTIST FILE / 001</span><span>DIR. IAN</span></div><div class="wordmark" aria-hidden="true">ROYZ</div><div class="bottom-credit micro">YOUR VOICE. YOUR WORLD. YOUR CALL.</div></div></section><div class="strip"><div><strong>Find your creative center</strong><span>Four directions, room for a hybrid</span></div><div><strong>Build around your real voice</strong><span>Separate ambition from evidence</span></div><div><strong>Leave with a first chapter</strong><span>A personalized artist + label deck</span></div><div><strong>Keep every answer</strong><span>Local save · export · return later</span></div></div><section class="intro-content"><div class="two-col"><div><span class="eyebrow">Before the first record</span><h2>Borrow the ambition.<br><span class="serif">Find your own language.</span></h2></div><div><p>Tyler, Kanye, Childish Gambino and Steve Lacy are useful creative references. This session asks what you respond to: complete worlds, storytelling, arrangement, intimacy, rhythm, performance.</p><p class="note">It does not decide which celebrity you are, measure talent, or judge a voice it has not heard. There are no “good artist” answers. Choose what you would actually make and practice.</p></div></div><div class="chapter-grid">${QUIZ.sections.map((s,i)=>`<div class="chapter-card"><span class="eyebrow">${String(i+1).padStart(2,'0')} / 06 QUESTIONS</span><h3>${esc(s.title.replace(/^\d+\s*\/\s*/,''))}</h3><p>${esc(s.description)}</p></div>`).join('')}<div class="chapter-card"><span class="eyebrow">AFTER THE SESSION</span><h3>Your private pitch deck</h3><p>Creative thesis, sound experiments, visual direction, voice lab, release gates and a 90-day campaign.</p></div><div class="chapter-card"><span class="eyebrow">THEN WE GO DEEPER</span><h3>A brief we can build from</h3><p>Export your answers. Bring them back with a voice sample and demos for a fully bespoke second pass.</p></div></div><div class="known"><span class="eyebrow">Built from your existing world</span><p>I inspected your original portraits and creative notes: cinematic low light, tailored clothing alongside relaxed streetwear, a personal archive, filmmaking and Southern storytelling. These are starting references, not a personality diagnosis.</p><p class="note">The portraits here come from your local IAN ROYZ archive. Your notes identify @notsoian as the personal home and @royzfilmz as the film portfolio. Live Instagram access failed, so this is not a current feed or audience audit. The quiz asks you what still fits.</p><p class="note">Answers stay in this browser; no account, analytics or upload service. Browser storage is not encrypted. Save a backup before switching devices or clearing browser data. Voice files in the listening lab are temporary and stay on your device.</p></div><div class="actions"><button class="primary" data-action="start">${count()?'Continue session':'Start with your instincts'} ↗</button>${count()?'<button class="secondary" data-action="review">Review saved answers</button>':''}</div></section><footer class="footer"><span>ROYZ / ARTIST DEVELOPMENT / PRIVATE WORKING MATERIAL</span><span>Every direction is a hypothesis until the music proves it.</span></footer>`;}
function quizHTML(){const q=QUESTIONS[state.index],s=QUIZ.sections[q.section],a=ans(q.id);return `<div class="app-shell"><aside class="sidebar"><div class="sidebar-head"><span class="eyebrow">Your session</span><p class="note">${count()} of ${QUESTIONS.length} answered</p></div><nav aria-label="Quiz chapters">${QUIZ.sections.map((s,i)=>`<button class="chapter-nav ${q.section===i?'active':''}" data-chapter="${i}" ${q.section===i?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title.replace(/^\d+\s*\/\s*/,''))}</button>`).join('')}</nav><div class="sidefoot"><img src="assets/royz-day.jpg" alt="Ian in a relaxed daytime portrait"><p>Build a world you can live in.</p><button class="textbtn" data-action="review">Review your answers ↗</button><br><button class="textbtn" data-action="home">Session overview</button></div></aside><section class="question-area"><div class="mobile-chapters"><label for="chapter-select" class="micro">CHAPTER</label><select id="chapter-select">${QUIZ.sections.map((s,i)=>`<option value="${i}" ${q.section===i?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div class="question-top"><span class="eyebrow">${esc(s.title)}</span><span class="micro">${String(state.index+1).padStart(2,'0')} / ${QUESTIONS.length}</span></div><div class="progress" role="progressbar" aria-label="Questions answered" aria-valuemin="0" aria-valuemax="42" aria-valuenow="${count()}"><div style="width:${count()/QUESTIONS.length*100}%"></div></div><h1 id="question-title">${esc(q.prompt)}</h1><p class="question-help">${esc(q.help|| (q.type==='text'?'Optional. Specific details will make the next conversation much better.':q.type==='multi'?'Choose the options that fit.':'Choose the answer you would actually act on. You can change it later.'))}</p>${q.type==='text'?`<textarea id="written-answer" class="answer-text" maxlength="5000" aria-labelledby="question-title" placeholder="${esc(q.placeholder||'Write it in your own words…')}">${esc(a||'')}</textarea><p class="note">Optional · preserved verbatim in your brief; not automatically interpreted.</p>`:`<div class="choices" role="${q.type==='multi'?'group':'radiogroup'}" aria-labelledby="question-title">${q.options.map((o,i)=>`<button class="choice" role="${q.type==='multi'?'checkbox':'radio'}" aria-checked="${Array.isArray(a)?a.includes(o.value):a===o.value}" tabindex="${q.type==='multi'||a===o.value||(!q.options.some(o=>o.value===a)&&i===0)?0:-1}" data-value="${esc(o.value)}"><span class="key" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></button>`).join('')}</div><button class="textbtn" data-action="unsure">${a==='__unsure'?'✓ Marked as still exploring':'Still exploring / I don’t know yet'}</button>`}${q.type!=='text'?`<details ${q.id==='references'?'open':''}><summary>${q.id==='references'?'Add exact songs and moments (optional)':'Add nuance in your own words (optional)'}</summary><label class="note" for="answer-note">${q.id==='references'?'Name 3–5 songs, the moments you love, and one sound you want to avoid. Links or timestamps help.':'If none of these fits perfectly, explain the difference. Your notes travel with your answers.'}</label><textarea id="answer-note" class="answer-text" style="min-height:100px" maxlength="5000" placeholder="Your notes…">${esc(state.notes?.[q.id]||'')}</textarea></details>`:''}<div class="question-footer"><button class="textbtn" data-action="back">← ${state.index?'Previous':'Overview'}</button><div class="actions"><button class="textbtn" data-action="review">Review</button><button class="primary" data-action="next" ${!answered(q)&&q.type!=='text'?'disabled':''}>${state.index===QUESTIONS.length-1?'Finish session':'Continue'} →</button></div></div><p class="note micro" style="margin-top:20px;letter-spacing:0">Your best guess is useful. Uncertainty is useful too. Neither is a talent score.</p></section></div>`;}
function reviewHTML(){const pending=QUESTIONS.filter(q=>q.type!=='text'&&!answered(q));return `<section class="review"><span class="eyebrow">Session review</span><h1>The beginning of<br><span class="serif">your artist brief.</span></h1><p>${count()} of 42 answered. ${pending.length?`${pending.length} choice questions remain. You can return to them or build a clearly marked partial brief.`:'Every choice question is answered. Written answers are optional.'}</p><div class="actions"><button class="primary" data-action="report">${pending.length?'Build partial brief':'Build my pitch deck'} ↗</button><button class="secondary" data-action="export">Save answers</button></div>${QUIZ.sections.map(s=>`<h2>${esc(s.title)}</h2>${s.questions.map(q=>`<div class="review-item"><div><strong>${esc(q.prompt)}</strong><p class="note">${esc(label(q.id))}</p>${state.notes?.[q.id]?`<p class="note">Your note: ${esc(state.notes[q.id])}</p>`:''}</div><button class="textbtn" data-edit="${q.id}">${answered(q)?'Edit':'Answer'} ↗</button></div>`).join('')}`).join('')}<div class="actions"><button class="primary" data-action="report">Build my pitch deck ↗</button><button class="textbtn" data-action="reset">Start a new session</button></div><p class="note">Starting over clears only this session after confirmation. Download a backup first if you want to keep it.</p></section>`;}
const PROFILES={
 world:{name:'The world builder',short:'World building',title:'A world with<br>your name on it.',thesis:'Royz builds a recognizable world around the songs: recurring images, characters and emotional rules that make each release feel like another scene.',reference:'Tyler is a reference for cohesive creative worlds—not a personality, wardrobe or voice to reproduce.',sound:'Try characterful alternative hip-hop with warm chords, dry drums and one recurring sound that links the songs.',visual:'A repeatable color, a recurring location and one everyday object with a changing meaning.',risk:'The campaign can become more finished than the music. Make the hook work without the film.',campaign:'Scenes from Royz',formats:['One scene, one hook: an ordinary place becomes the setting for the chorus.','A recurring object appears in each clip, with its meaning changing.','A short director’s note shows one musical decision and its visual counterpart.'],prompt:'Alternative hip-hop, 88 BPM, warm electric piano, dry syncopated drums, melodic bass, intimate conversational delivery, narrow comfortable melody, recurring two-note motif, small first verse, wider final chorus, no imitation of a named performer.',demos:['The opening scene — one location, one desire, one repeated phrase.','The contradiction — confident rhythm beneath an emotionally uncertain lyric.','The closing image — a restrained hook whose last line changes the meaning.']},
 story:{name:'The cinematic storyteller',short:'Storytelling',title:'Make the record<br><i>feel like a scene.</i>',thesis:'Royz turns lived moments into songs and films. The signature is an unmistakable point of view: specific characters, sharp details and an emotional turn.',reference:'Childish Gambino is a reference for working across narrative forms—not a requirement to sing, act or sound like him.',sound:'Try conversational rap and melodic speech over spacious, cinematic alternative R&B. Let cadence carry meaning before asking for vocal range.',visual:'Begin with real locations, natural dialogue and a recurring point of view. Every clip needs a situation, not just attractive footage.',risk:'The story can delay the part people want to replay. Keep a stand-alone hook and cut exposition.',campaign:'Things I couldn’t say on camera',formats:['A real-life detail opens a 20-second scene; the song supplies the turn.','A line from the song becomes a quiet direct-to-camera confession.','Show the mundane moment that became the lyric, then the finished musical moment.'],prompt:'Cinematic alternative R&B and conversational hip-hop, 82 BPM, muted piano, round bass, sparse drums, atmospheric room texture, speech-led verse, short narrow-range hook, emotionally clear phrasing, a restrained arrangement turn after verse two.',demos:['A scene — name a place, an object and something left unsaid.','A perspective switch — the same situation from a less flattering angle.','An admission — the chorus says what the verse keeps avoiding.']},
 groove:{name:'The intimate groove maker',short:'Intimate groove',title:'Close enough<br><i>to feel human.</i>',thesis:'Royz makes intimate, tactile songs people want to live with. The appeal comes from a convincing pocket, small personal details and a recognizable vocal presence.',reference:'Steve Lacy is a reference for economy, intimacy and groove—not a guarantee that a minimal production needs less craft.',sound:'Try restrained alternative R&B or indie soul: tactile guitar or keys, melodic bass and a low, repeatable hook.',visual:'Use close framing, daylight or a single practical lamp, casual movement and room for the face to do the work.',risk:'Mood alone can blur into generic playlist music. Give each song a line, rhythm or sound that belongs specifically to Royz.',campaign:'Room tone',formats:['The same hook in three everyday spaces; let the mood change naturally.','A close-up live take with your actual voice and minimal staging.','A texture diary: an object, a sound and the lyric they led to.'],prompt:'Intimate alternative R&B, 96 BPM, dry pocket drums, tactile clean guitar, melodic rounded bass, sparse warm keys, low comfortable vocal range, brief repeated hook, subtle human timing, uncluttered arrangement, no oversized vocal runs.',demos:['The pocket — one groove that stays interesting for sixty seconds.','The close-up — a personal lyric with almost no decorative production.','The after-hours version — the same emotional center with a slower pulse.']},
 sonic:{name:'The sonic architect',short:'Sonic architecture',title:'Give the feeling<br><i>its own sound.</i>',thesis:'Royz directs arrangements with a distinct emotional architecture. Voice, contrast and texture become choices with a purpose, supported by a memorable song.',reference:'Kanye is a reference for ambitious arrangement and production direction—not a recommendation to borrow his public behavior or reproduce existing recordings.',sound:'Try production-led alternative hip-hop: rhythmic vocal phrases, a strong motif and one purposeful contrast between sections.',visual:'Connect one physical material to the record’s texture. Use scale, shadows and negative space to make the production feel tangible.',risk:'Endless versions can disguise an unfinished song. Freeze a small palette and set a clear stopping rule.',campaign:'Built from a feeling',formats:['A stripped motif transforms into the chorus in one concise edit.','Show two arrangement choices and explain the feeling behind the one you kept.','Film a physical texture or movement that mirrors the record’s central rhythm.'],prompt:'Production-led alternative hip-hop, 92 BPM, heavy restrained drums, original choral-like synth texture, rounded sub bass, rhythmic spoken lead, memorable short motif, deliberate silence before the hook, one dramatic but coherent arrangement change, no sampled existing recordings.',demos:['The motif — an original two-bar musical idea carries the whole sketch.','The contrast — quiet verse and expansive hook, with one emotional reason.','The restraint test — remove half the layers and see whether the song survives.']}
};
function score(){const raw={world:0,story:0,groove:0,sonic:0};let n=0;for(const q of SCORED){const values=Array.isArray(ans(q.id))?ans(q.id):[ans(q.id)];const opts=q.options.filter(o=>values.includes(o.value)&&o.scores);if(opts.length){n++;for(const o of opts)for(const k of Object.keys(raw))raw[k]+=(o.scores[k]||0)/opts.length;}}const sorted=Object.entries(raw).sort((a,b)=>b[1]-a[1]);const total=Object.values(raw).reduce((a,b)=>a+b,0);return{raw,rank:sorted.map(x=>x[0]),answered:n,totalQuestions:SCORED.length,total,shares:Object.fromEntries(sorted.map(([k,v])=>[k,total?Math.round(v/total*100):0])),tied:total>0&&sorted[0][1]===sorted[1][1],gap:sorted[0][1]-sorted[1][1]};}
function context(){const sc=score();const primary=sc.total?sc.rank[0]:null,secondary=sc.total?sc.rank[1]:null,candidates=sc.rank.filter(k=>sc.raw[k]>0&&sc.raw[sc.rank[0]]-sc.raw[k]<=3);let p=primary?PROFILES[primary]:null;if(candidates.length>1){const profiles=candidates.map(k=>PROFILES[k]);p={name:'A creative hybrid',short:profiles.map(p=>p.short).join(' + '),thesis:'Your answers support several creative directions: '+profiles.map(p=>p.short.toLowerCase()).join(', ')+'. Give each its own short demo before combining them into a Royz identity.',reference:profiles.map(p=>p.reference).join(' '),sound:'Compare separate sketches in '+profiles.map(p=>p.short.toLowerCase()).join(', ')+'. Keep the same original lyric and vocal range so you can hear what the arrangement changes.',visual:'Try one visual treatment for each leading direction using the same location and clothing. Let the finished musical sketch decide what belongs.',risk:'The directions are close. Do not let an arbitrary score order choose your first record; judge the actual demo results.',campaign:'The Royz screen tests',formats:profiles.map(p=>p.formats[0]),prompt:'Create separate arrangement trials, keeping the same original lyric and comfortable range. '+profiles.map(p=>p.short+': '+p.prompt).join(' / '),demos:profiles.map(p=>p.short+' — '+p.demos[0])};}const unknown=QUESTIONS.filter(q=>q.type!=='text'&&(!answered(q)||ans(q.id)==='__unsure'));const lowtime=ans('hours')==='under3',midtime=ans('hours')==='3to6',hoursKnown=['under3','3to6','7to12','13plus'].includes(ans('hours'));const goal=ans('goal');const phase=goal==='identity'||!goal||goal==='__unsure'?'development':goal==='catalog'?'catalog':goal==='audience'?'audience':'single';const ready=ans('catalog')==='masters'&&['tested','workflow'].includes(ans('suno'));const release=phase!=='development';const uncertain=!sc.total||sc.answered<10||unknown.length>8;return{sc,primary,secondary,p,candidates,unknown,lowtime,midtime,hoursKnown,phase,ready,release,uncertain};}
function voicePlan(){const v=ans('voice_priority');if(!v||v==='__unsure')return{title:'First test: a recorded lead and a generated candidate',body:'Your voice requirement is still open. Record a short actual vocal and compare it with a generated candidate of the same phrase before choosing a workflow.',steps:'Decide whether you need your actual performance on the master, or whether a clearly credited generated performance fits. The plan remains provisional until that choice is made.'};if(v==='synthetic_ok')return{title:'Directed generated lead, with an honest identity test',body:'Test Suno’s Voices output against your raw take. Treat the result as a generated performance using a model of your voice, and credit it accurately. If likeness is weak, do not describe the singer as recognizably you.',steps:'Keep your original lyrics, source take, generation settings and edit history. Add actual spoken or sung moments where they improve the song. Compare several phrases, not just the strongest ten seconds.'};if(v==='hybrid')return{title:'Your recorded lead; generated support where it earns its place',body:'Anchor the song with actual recorded lead phrases. Use Suno for arrangements and deliberately chosen supporting layers. A generated harmony is a separate production choice, not proof of your own singing ability.',steps:'Export usable instrumental material, record multiple short lead takes in a comfortable key, then place generated textures around them. Keep a clear record of which parts are performed and generated.'};return{title:v==='own_lead'?'Your actual recorded lead is the release requirement':'Your real takes, shaped around your current range',body:'Use Suno to explore backing tracks, structure and arrangements. Record your own lead over the selected instrumental material, then edit, comp and tune only as much as the song calls for. A voice model does not preserve the original performance.',steps:'Record short phrases, use a key that suits your comfortable notes and compare a dry take with the finished vocal. If the backing has vocal bleed or artifacts, revise it before adding more processing.'};}
function tensions(c){const t=[];if(['own_lead','own_processed'].includes(ans('voice_priority'))&&ans('authenticity')==='release_generated')t.push('Your answers pull in two directions: you want your actual recorded lead, but would also release a generated singer. Decide which rule applies to the first single before finishing vocals.');if(c.lowtime&&['catalog','audience'].includes(ans('goal')))t.push('Your ambition exceeds the available hours. Begin with one strong sketch and one repeatable content format; move the release window if the work needs it.');if(['small','stage'].includes(ans('performance'))&&['limited','untested'].includes(ans('voice')))t.push('You want live performance before your vocal baseline is proven. Make a comfortable 60-second live version the next milestone.');if(ans('budget')==='zero')t.push('The current budget is $0. Use existing access and keep drafts private until you confirm the applicable Suno commercial rights and any release costs. Do not build the plan around a new paid subscription.');if(ans('catalog')!=='masters'&&c.release)t.push('The release plan is conditional: your answers do not establish a finished master. Lock a date only after the song, vocal and technical checks pass.');if(['none','upload',undefined,'__unsure'].includes(ans('suno')))t.push('Your Suno voice workflow is not yet validated. The listening test comes before launch assets or promotion spend.');if(ans('practice')==='minimal'&&['small','stage'].includes(ans('performance')))t.push('A live-led identity needs rehearsal time. Either make room for practice or begin with recording and visual releases.');if(c.unknown.length)t.push(`${c.unknown.length} choice answers are missing or marked “still exploring.” Treat the relevant recommendations as trial options.`);return t;}
function sourcesHTML(){return `<ol class="source-list"><li><a href="https://help.suno.com/en/articles/11362369" target="_blank" rel="noopener">Suno — Voices: use your voice</a>. Official setup guidance, clean vocal input, verification, age and location eligibility. Checked September 18, 2026.</li><li><a href="https://help.suno.com/en/articles/11362433" target="_blank" rel="noopener">Suno — Voices FAQ</a>. Likeness troubleshooting; a voice feature is not a guarantee of a faithful result. Older FAQ model references may lag your current interface.</li><li><a href="https://help.suno.com/en/articles/9601665" target="_blank" rel="noopener">Suno — paid subscription rights</a> (updated September 3, 2026) and <a href="https://help.suno.com/en/articles/13614785" target="_blank" rel="noopener">September changes FAQ</a>. Current guidance ties commercial rights to downloads while paid. Older help pages discuss creation-time eligibility; verify the terms applicable to each track and keep records.</li><li><a href="https://help.suno.com/en/articles/13926209" target="_blank" rel="noopener">Suno — download allowances</a> (updated September 9, 2026). Check current account access and limits before planning a large export workflow.</li><li>Local context: the artist's existing film-universe notes and two archive portraits. These describe the film work, not an approved music identity.</li><li>Instagram: requested profiles @notsoian and @royzfilmz. OpenCLI browser connection failed; public web search did not yield a usable feed. Current posts, engagement and audience fit remain unverified.</li></ol>`;}
function card(title,body,eyebrow=''){return `<div class="card">${eyebrow?`<span class="eyebrow">${esc(eyebrow)}</span>`:''}<h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;}
function slide(id,n,title,body){return `<section class="slide" id="${id}"><div class="slide-inner"><div class="slide-index micro"><span>ROYZ / PRIVATE ARTIST BRIEF</span><span>${String(n).padStart(2,'0')} / ${title.toUpperCase()}</span></div>${body}</div></section>`;}
function reportHTML(){const c=context(),{sc,p}=c;const artist=state.lens==='artist';const hybrid=c.candidates.length>1;const vp=voicePlan();const selectedVoice=label('voice'),pace=c.lowtime?'one 45-minute writing session, one 45-minute recording session and one 30-minute review':c.midtime?'two 60-minute music sessions, one 45-minute vocal practice block and one 45-minute content batch':'three focused music sessions, short regular vocal practice and one batched visual session';const cadence=c.lowtime?'One simple post per week at most, made from the session you already recorded. Your hours override a higher posting preference.':{frequent:'Up to four short posts per week, only if the music sessions still happen.',steady:'Two strong posts per week: one musical moment and one story or process clip.',weekly:'One strong post per week. Reuse the same shoot for alternate edits.',batch:'Batch a small set of clips around each milestone; avoid an always-on schedule.'}[ans('posting')]||'Begin with one useful post per week; increase only when it is sustainable.';const channel={instagram:'Use your existing Instagram connection as the first testing room. Test whether those viewers actually want the music; film engagement is not music demand.',shortvideo:'Use the short-video platform where people already respond. Test a musical opening against a narrative opening.',youtube:'Put the full scene or performance on YouTube, then cut a short musical entry point from the same shoot.',offline:'Begin with a small private listening circle and one real local performance or film showing if practical.',none:'Recruit five willing listeners from the specific scene you want to reach. Ask for private feedback before building a broad content funnel.'}[ans('channel')]||'Choose one reachable listener group and one primary channel before expanding.';const budget={zero:'Spend $0 on this development sprint. Use existing gear, free recording options and the Suno access you already have. Public monetization waits for verified rights.',under75:'Keep monthly spend below $75. Verify what your existing tools cover; prioritize one actual bottleneck and avoid promotion spend.', '75to250':'Keep monthly spend within $75–$250. After your tests identify a problem, consider a bounded vocal or mix session before buying new gear.', '250plus':'Set a specific monthly ceiling before spending. Reserve most of the first allocation until the lead vocal and song direction are proven.'}[ans('budget')]||'Set a monthly ceiling before choosing any paid service. This brief does not assume a paid budget.';const goalTitles={development:'90 days to find the record.',single:'One single. An earned release.',catalog:'A small body of work. One clear center.',audience:'A repeatable rhythm. Real listeners.'};const timeline=c.phase==='development'?[['Days 1–14','Find the baseline','Record dry voice samples. Make three short sound sketches. Collect exact musical references.'],['Days 15–35','Choose the center','Compare the sketches privately. Finish one full demo and rehearse its simplest hook.'],['Days 36–65','Build three demos','Carry one vocal approach and a small sound palette across three songs. Shoot one visual test.'],['Days 66–90','Make the decision','Run another listening test. Keep, revise or abandon the direction with evidence. A public release is optional.']]:[['Days 1–14','Prove the voice','Capture your real vocal baseline; test the workflow and three short sound ideas.'],['Days 15–35',c.phase==='catalog'?'Find the common thread':'Finish the lead idea',c.phase==='catalog'?'Make three related demos. Choose one lead track; finish that before expanding.':'Choose one song. Rewrite weak lines, finish the lead vocal and test on ordinary playback.'],['Days 36–65','Build the release package',c.phase==='audience'?'Test a repeatable format with your chosen audience. Keep the song central; note meaningful replies.':'Only after the song passes: finish artwork, one hero film and a small reusable clip library.'],['Days 66–90','Release if it earns it','If voice, rights and master checks pass, release and learn. If they fail, revise and move the date.']];const deckTitle=!p?'Your direction is<br><i>still open.</i>':hybrid?'A hybrid worth<br><i>putting to the test.</i>':p.title;
return `<div class="deck"><div class="deck-top"><div><span class="eyebrow">Your working pitch / ${c.uncertain?'exploratory':'provisional'}</span><p class="note" style="margin:5px 0">${count()}/42 answered · ${sc.answered}/${sc.totalQuestions} creative choices · no audio assessed</p></div><div class="lens-switch" aria-label="Presentation perspective"><button data-lens="artist" class="${artist?'active':''}" aria-pressed="${artist}">The artist</button><button data-lens="label" class="${!artist?'active':''}" aria-pressed="${!artist}">The label</button></div><div class="report-actions"><button class="secondary" data-action="present">Present ↗</button><button class="secondary" data-action="print">Save PDF</button><button class="secondary" data-action="export">Export answers</button><button class="textbtn" data-action="review">Edit session</button></div></div><nav class="deck-nav" aria-label="Pitch sections">${['Thesis','Creative DNA','Sound','Voice','Visual world','Audience','Campaign','Operations','Release gates','Listening lab','Next session'].map((x,i)=>`<a href="#slide-${i}">${String(i+1).padStart(2,'0')} ${x}</a>`).join('')}</nav>
${slide('slide-0',1,'The thesis',`<div class="deck-cover"><div><span class="eyebrow">${artist?'A direction you can inhabit':'A proposition we still need to prove'}</span><h1>${deckTitle}</h1><p class="lead">${p?esc(artist?p.thesis:'Develop Royz around '+p.short.toLowerCase()+', then validate the actual vocal identity, the song and repeatable listener interest before increasing output.'):'Answer more creative questions to establish a direction. For now, build a voice baseline and explore the four sound sketches without choosing a persona.'}</p>${p?`<span class="tag">${esc(p.name)}</span>${(hybrid?c.candidates:sc.raw[sc.rank[1]]>0?[sc.rank[1]]:[]).map(k=>`<span class="tag">${esc(PROFILES[k].short)}</span>`).join('')}`:''}<p class="note">This is a rules-based development brief from your selections. It is not a prediction of success, a talent assessment or a final A&R verdict.</p></div><img class="deck-photo" src="assets/royz-day.jpg" alt="Ian seated in daylight wearing sunglasses, a knit polo and sneakers"></div>`)}
${slide('slide-1',2,'Creative DNA',`<span class="eyebrow">Preference map / not a personality test</span><h2>${artist?'What your instincts<br><span class="serif">keep reaching for.</span>':'The creative bet,<br><span class="serif">with its evidence.</span>'}</h2><div class="two-col"><div>${sc.rank.map(k=>`<div class="bar-row"><span>${PROFILES[k].short}</span><div class="bar"><div style="width:${sc.shares[k]}%"></div></div><small>${sc.shares[k]}%</small></div>`).join('')}<p class="note">Share of points from ${sc.answered} answered creative questions. Each scored choice carries equal weight. Practical constraints and written responses do not change these scores. Percentages are rounded.</p></div><div><p class="lead">${!p?'No scored preferences yet.':sc.tied?'Your strongest scores are tied. Keep the tied directions in the first demo test; their display order is not a ranking.':hybrid?'Your leading directions are separated by at most one answer. Test them instead of treating the small lead as a verdict.':esc(p.name)+' has the clearest preference signal in this session.'}</p><p class="note">${p?esc(p.reference):'World building, storytelling, groove and production direction remain equally open.'}</p></div></div><div class="cards">${(p?SCORED.filter(q=>c.candidates.some(k=>q.options.find(o=>o.value===ans(q.id))?.scores?.[k]>0)).slice(0,3):[]).map(q=>card(q.prompt,label(q.id),'Your evidence')).join('')}</div><p class="note">Your declared references are creative lenses only. This framework does not claim those artists fit into a single category.</p>`)}
${slide('slide-2',3,'The sound',`<span class="eyebrow">A small palette / three decisive experiments</span><h2>Find the song<br><span class="serif">before the mythology.</span></h2><p class="lead">${p?esc(p.sound):'Make one conversational rap sketch, one intimate groove sketch and one scene-led melodic sketch. Keep your real vocal comfort as the constant.'}</p><div class="cards">${(p?p.demos:['A rhythmic speaking-led hook.','A comfortable low-range melody over a simple groove.','A story with a clear emotional turn.']).map((s,i)=>card('Demo '+String(i+1).padStart(2,'0'),s,'45–75 seconds first')).join('')}</div><div class="known"><span class="eyebrow">Starting arrangement brief · adapt to your actual voice</span><p>${esc(p?p.prompt:'Use a restrained backing, a comfortable vocal range and a short memorable hook. Compare several tempos with the same original lyric.')}</p><p class="note">This is an experiment, not a promised result. Use your own original lyrics and vocal source. If actual recorded lead is your requirement, use generated vocal versions only as arrangement references and record the final lead yourself.</p></div><div class="cards">${card('Your delivery preference',label('delivery'))}${card('Your lyrical territory',label('lyric'))}${card('The edit that matters',p?p.risk:'Choose a sound after listening to the results, not from its description.')}</div>${state.notes?.references?`<div class="known"><span class="eyebrow">Your exact listening references</span><p style="white-space:pre-wrap">${esc(state.notes.references)}</p><p class="note">Preserved for creative review; these tracks have not been fetched or analyzed by this page.</p></div>`:''}<p class="note">Before a final sound recommendation: bring three specific song references, the exact 15–30 second moments you love, and one reference you definitely want to avoid.</p>`)}
${slide('slide-3',4,'Voice + Suno',`<span class="eyebrow">The voice is a production decision, not a promise</span><h2>Make it convincing.<br><span class="serif">Then make it recognizably yours.</span></h2><p class="lead">${esc(vp.title)}</p><div class="two-col"><div><p>${esc(vp.body)}</p><p class="note">${esc(vp.steps)}</p><p class="note">Your baseline: ${esc(selectedVoice)} No recording has been analyzed here.</p></div><div class="known"><span class="eyebrow">What is verified</span><p>Suno’s official Voices guide supports creating a voice profile from your recording. Its FAQ also includes troubleshooting when results do not sound like you. Likeness and musical quality must be tested separately.</p><p class="note">Voices requires age 18+ and may be unavailable in some locations. Check the currently supported model in your account; older FAQs can lag model changes. If unavailable, record your real lead outside Suno over suitable instrumental material.</p><a class="note" href="https://help.suno.com/en/articles/11362369" target="_blank" rel="noopener">Read the official Voices guide ↗</a></div></div><div class="cards">${card('01 / Establish a dry baseline',({phone:'Use your phone in a quiet soft-furnished room, at a consistent distance. Record without a backing track in the room.',usb:'Check microphone distance and input level, turn off avoidable room noise, and record a clean dry take.',interface:'Record a dry mono lead with a comfortable headphone mix and enough level headroom. Keep processing reversible.',studio:'Ask your engineer for dry source takes as well as the comp. Compare a comfortable key before final production.'})[ans('recording')]||'Record speech, rhythm and a comfortable melody in a quiet room. Keep original files. Your setup is not yet specified.')}${card('02 / Compare the same phrase','Use an original short lyric and matched playback loudness. Compare your dry recording, a processed take and a generated version. Note identity, emotion, consonants and odd artifacts.')}${card('03 / Repeat and verify','Have a few listeners who know your voice compare versions without knowing which tool made them. Test strangers separately for song appeal. Repeat with a second phrase before choosing.')}</div><p class="note">If the generated singer sounds strong but unlike you, use the useful arrangement and re-record the lead, or frame the generated role accurately. “My own voice” and “my own recorded performance” are different claims.</p>`)}
${slide('slide-4',5,'The visual world',`<span class="eyebrow">Your existing image is an asset / your answers set the direction</span><h2>You already have<br><span class="serif">a camera language.</span></h2><div class="two-col"><div><p class="lead">${p?esc(p.visual):'Test a daytime portrait sequence and a low-light scene before locking the first music identity.'}</p><p>In the inspected archive: dramatic tailored portraits and relaxed daytime styling. The proposed visual bridge is intimacy with cinematic control. That is a creative interpretation of the images, not a personality judgment.</p><p class="note">${ans('universe')==='separate'?'You chose a separate artist identity. Develop a distinct music wordmark and palette; use the existing photos as reference rather than treating the film brand as a mandate.':ans('universe')==='shared'?'You chose one creative universe. Let the film work introduce the music naturally, with a recognizable caption and framing language.':'You have room for a musical chapter connected to the film archive. Test the relationship with one visual before redesigning every profile.'}</p></div><div class="known"><span class="eyebrow">Your direction, in your own selections</span><p><strong>First scene:</strong> ${esc(label('visual'))}</p><p><strong>Wardrobe:</strong> ${esc(label('wardrobe'))}</p><p><strong>Repeatable format:</strong> ${esc(label('series'))}</p><p><strong>What you can make now:</strong> ${esc(label('visual_skill'))}</p></div></div><div class="cards">${card('A visual grammar','Start with one location, one recurring visual detail and two lighting conditions. Choose clothing you can wear repeatedly and move in.')}${card('A useful shoot list','Capture a clean portrait, a full-song locked shot, three close details and several vertical hook takes. Keep space for titles and captions.')}${card('A boundary worth keeping',ans('visual_details')?ans('visual_details'):'Use the optional style answer to tell us what feels like you and what feels like costume. Do not lock the final wardrobe from references alone.')}</div>`)}
${slide('slide-5',6,'The audience',`<span class="eyebrow">A real first room / no invented audience numbers</span><h2>${artist?'Who needs<br><span class="serif">this version of you?</span>':'Find repeat interest.<br><span class="serif">Then expand the room.</span>'}</h2><p class="lead">${esc(label('listener'))}</p><div class="cards">${card('The listening moment',label('moment'))}${card('The relationship',label('bond'))}${card('The first channel',channel)}</div><p class="quote">${esc(ans('listener_words')||'The aim: someone remembers a line, asks for the full song, or returns without being prompted.')}</p><p class="note">${ans('listener_words')?'Your words, preserved verbatim.':'This is a proposed learning objective, not an existing fan response.'}</p><div class="known"><span class="eyebrow">A private test before a public narrative</span><p>Invite a small group who likes the general musical territory. Play the song without a biography or explanation of the tool. Ask what they remember, where attention dropped, whether they would replay it, and what felt distinctive. Then explain the workflow honestly if asked.</p><p class="note">${ans('feedback')==='difficult'?'Start with two trusted listeners and ask for one strength and one specific revision each. Keep the first review small.':ans('feedback')==='coach'?'Ask one experienced collaborator to turn feedback into two concrete edits before testing again.':'Collect specific reactions before discussing your intended meaning.'}</p><p class="note">Keep voice-recognition feedback from people who know you separate from music-interest feedback. A friend being supportive is different evidence from a listener asking for the track again.</p></div>`)}
${slide('slide-6',7,'The campaign',`<span class="eyebrow">Working concept / ${p?esc(p.campaign):'first chapter'}</span><h2>${goalTitles[c.phase]}</h2><p class="lead">${artist?'Make the process serve the record. Every public piece should reveal a real sound, scene or choice.':'Release readiness controls the calendar. This is a development schedule with decision points, not a promised launch date.'}</p><p class="note">${c.lowtime?'Your available time is under three hours weekly. Treat these as sequence milestones; extend the dates rather than skipping the voice and song work.':!c.hoursKnown?'Weekly capacity is not established. Dates are placeholders until you choose a sustainable time commitment.':'The schedule assumes your stated hours remain available. Review scope weekly.'}</p><div class="timeline">${timeline.map(([d,h,b])=>`<div><span class="eyebrow">${d}</span><h3>${h}</h3><p>${b}</p></div>`).join('')}</div><div class="cards">${(p?p.formats:['Share a short musical moment with a clear emotional center.','Show a real vocal take and one arrangement decision.','Film a small scene that earns its connection to the lyric.']).map((s,i)=>card('Content format '+(i+1),s)).join('')}</div><p><strong>Cadence:</strong> ${esc(cadence)}</p><p class="note"><strong>Your own campaign instinct:</strong> ${esc(label('campaign_hook'))}. Use this as the first concept to test against the formats above.</p>${c.release?`<table class="report-table"><thead><tr><th>Relative to an approved release</th><th>Make</th><th>Learn</th></tr></thead><tbody><tr><td>−21 to −14 days</td><td>Final master, cover, credits, distribution checks; one hero visual.</td><td>Does the full song hold up beyond its best hook?</td></tr><tr><td>−14 to −7 days</td><td>Test two different openings from one footage batch.</td><td>Which creates meaningful interest in the music?</td></tr><tr><td>Release day</td><td>Publish the full listening destination and strongest visual.</td><td>Can an interested person find the full song easily?</td></tr><tr><td>+7 to +21 days</td><td>Actual-voice take, alternate scene and a considered follow-up.</td><td>Do listeners return, save it or ask for the next song?</td></tr></tbody></table>`:'<p class="note">Your selected win is development. Keep the public rollout optional until a song earns it.</p>'}`)}
${slide('slide-7',8,'The operating plan',`<span class="eyebrow">${artist?'Protect the work':'Manage the scope'}</span><h2>A practice you<br><span class="serif">can keep.</span></h2><div class="cards">${card('Weekly rhythm',c.hoursKnown?'Start with '+pace+'. Reduce scope before cutting the review.':'Choose dependable weekly hours first. Until then, aim for one writing session and one recorded experiment.')}${card('Budget rule',budget)}${card('Team shape',ans('team')==='audio'?'Use your audio collaborator for vocal recording, playback review and a bounded finish. Keep your creative brief and final decisions explicit.':ans('team')==='solo'?'Build around setups you can run alone. Use outside feedback for decisions, and keep shoots simple.':'Give collaborators one clear job per session: capture, listen or review. Do not assume availability beyond what they have committed.')}</div><table class="report-table"><thead><tr><th>Decision</th><th>Your answer</th><th>Operating implication</th></tr></thead><tbody><tr><td>Performance</td><td>${esc(label('performance'))}</td><td>${['small','stage'].includes(ans('performance'))?'Reserve rehearsal time and build a reduced arrangement you can actually perform.':'Start with a believable camera performance or private vocal take; expand when ready.'}</td></tr><tr><td>Practice</td><td>${esc(label('practice'))}</td><td>${ans('practice')==='minimal'?'Write within your present range. Avoid a release concept that depends on rapid vocal improvement.':'Record the same short phrase regularly so improvement is audible, not just felt.'}</td></tr><tr><td>Main bottleneck</td><td>${esc(label('bottleneck'))}</td><td>${({voice:'Separate taste from self-consciousness with a blind listening comparison.',direction:'Freeze one sound palette for the three-demo experiment.',craft:'Finish one full arrangement before creating more sketches.',exposure:'Begin with a trusted private listening room and truthful process language.',capacity:'Shrink the scope to one song and one content format.'})[ans('bottleneck')]||'Use the next session to name the specific task that keeps stalling.'}</td></tr></tbody></table><div class="known"><span class="eyebrow">How to describe the process</span><p>${ans('disclosure')==='process'?'Show an original lyric or vocal take alongside the arrangement, and explain exactly what changed.':ans('disclosure')==='central'?'Make the human and generated contributions visible in the concept, with accurate credits for both.':'Keep a short, truthful process statement with the credits. Name what you wrote, what you actually recorded and what was generated.'}</p><p class="note">Working wording to edit only after it is true: “I wrote [specific contribution], recorded [specific vocal parts], and used Suno for [specific generated parts]. I directed and edited [specific changes].”</p></div><p class="note">No streaming-income forecast is included. There is no evidence yet to support one. Early success is a better song, a repeatable process and listeners who choose to return.</p>`)}
${slide('slide-8',9,'The release gates',`<span class="eyebrow">A beautiful rollout cannot rescue an unconvincing record</span><h2>${artist?'Keep the standard<br><span class="serif">honest.</span>':'Approve the song.<br><span class="serif">Then approve the spend.</span>'}</h2><p class="lead">${p?esc(p.risk):'Choose one direction to test before increasing production scope.'}</p>${tensions(c).map(t=>`<div class="tension">${esc(t)}</div>`).join('')}<table class="report-table"><thead><tr><th>Gate</th><th>Evidence to collect</th><th>If it fails</th></tr></thead><tbody><tr><td>Identity</td><td>The lead follows your declared actual-voice or generated-voice rule; recognition is checked separately.</td><td>Replace or re-record the lead; revise the concept or credits honestly.</td></tr><tr><td>Song</td><td>Listeners can name a memorable moment and explain where attention drops.</td><td>Rewrite structure or hook; test again.</td></tr><tr><td>Playback</td><td>Full-song checks on headphones and ordinary speakers; no distracting artifacts, clipping or vocal bleed.</td><td>Fix the source, edit or mix problem before distribution.</td></tr><tr><td>Rights + credits</td><td>Applicable Suno terms, paid-download records if relevant, original inputs, collaborator permissions and accurate credits.</td><td>Resolve the specific missing permission or eligibility before commercial release.</td></tr><tr><td>Performance</td><td>A simple version you can deliver in the format you intend to promote.</td><td>Change key, simplify, rehearse or choose a recording-led launch.</td></tr></tbody></table><p class="note">Your chosen review approach: ${esc(label('quality_gate'))}. These are proposed release standards, not completed checks. Suno’s commercial-use grant does not itself guarantee copyright protection. Its September 2026 guidance differs from older help text; verify your track’s applicable terms before distribution.</p>`)}
${slide('slide-9',10,'The listening lab',`<span class="eyebrow">Optional / your ears, with a fair comparison</span><h2>Does it sound<br><span class="serif">like Royz?</span></h2><p class="lead">Load a dry vocal and the candidate version of the same phrase. Listen at similar loudness. This page plays your files locally; it does not analyze, upload or automatically judge them.</p><div class="listening"><div class="listen-card"><span class="eyebrow">A / actual recorded voice</span><p class="note">A short original phrase, without backing music.</p><label for="audio-a" class="micro">CHOOSE LOCAL AUDIO</label><input type="file" id="audio-a" accept="audio/*"><audio id="player-a" controls preload="metadata"></audio><p id="name-a" class="note">No audio selected</p></div><div class="listen-card"><span class="eyebrow">B / candidate output</span><p class="note">A processed take or generated version of that phrase.</p><label for="audio-b" class="micro">CHOOSE LOCAL AUDIO</label><input type="file" id="audio-b" accept="audio/*"><audio id="player-b" controls preload="metadata"></audio><p id="name-b" class="note">No audio selected</p></div></div><div class="two-col"><div class="ratings">${[['identity','Recognizably my voice'],['emotion','Emotional delivery'],['artifacts','Clean, natural-sounding details'],['repeatable','Works across a second phrase']].map(([id,name])=>`<label class="rating" for="rating-${id}"><span>${name}</span><select id="rating-${id}" data-rating="${id}"><option value="">Not tested</option>${[1,2,3,4,5].map(i=>`<option value="${i}" ${state.ratings[id]===String(i)?'selected':''}>${i} / 5 ${i===1?'— weak':i===5?'— strong':''}</option>`).join('')}</select></label>`).join('')}</div><div class="known"><span class="eyebrow">Your self-assessment</span><p id="lab-result"></p><p class="note">Suggested studio heuristic: aim for 4/5 or better in every category before advancing this vocal candidate. This is not an objective test. If your rule requires an actual recorded lead, a generated performance still does not meet that rule.</p></div></div><p class="note">Ratings are saved and exported. Audio is not saved in your session or backup. Reattach files after reloading. This lab does not produce an AI voice evaluation.</p>`)}
${slide('slide-10',11,'The next session',`<span class="eyebrow">The first brief is a starting point</span><h2>Bring back the answers.<br><span class="serif">Then we build the campaign.</span></h2><p class="lead">Download the answers file and bring it back with your raw vocal, the strongest demos and exact musical references. That enables a proper creative review and a more specific Royz pitch.</p><div class="cards">${card('Your north star',ans('identity')||'Optional identity notes are still open. What do you want to keep unmistakably yours?')}${card('Your intended meaning',ans('listener_words')||'Optional listener-intent notes are still open.')}${card('Your non-negotiable',ans('nonnegotiable')||'Optional boundaries are still open. Name what you will not perform just to attract attention.')}</div><p class="note">Written responses above are preserved verbatim. They are not interpreted by a language model inside this page. The export carries all ${QUESTIONS.length} questions and choices for our next session.</p><div class="report-actions"><button class="primary" data-action="export">Download answers JSON ↗</button><button class="secondary" data-action="markdown">Download written brief</button><button class="secondary" data-action="print">Print / save PDF</button><button class="textbtn" data-action="import">Load a backup</button></div><h3 style="margin-top:45px">Evidence, limits and source notes</h3>${sourcesHTML()}<details><summary>See the complete answer record</summary>${QUESTIONS.map(q=>`<p><strong>${esc(q.prompt)}</strong><br>${esc(label(q.id))}${state.notes?.[q.id]?'<br>Your note: '+esc(state.notes[q.id]):''}</p>`).join('')}</details><details><summary>How the recommendation is calculated</summary><p>The ${SCORED.length} creative questions each give three points to the selected direction. The relative shares above use only answered scored questions. Ties remain ties; a lead of one answer or less is treated as a hybrid to test. Uncertain and missing answers contribute no points. Practical selections shape the voice workflow, budget, workload, channel, campaign and cautions. Written responses are retained without automatic interpretation. This is a custom planning framework, not a validated psychological test.</p></details>`)}<footer class="footer"><span>ROYZ / VERSION 01 / SEPTEMBER 2026</span><span>Your creative authority stays with you.</span></footer><div class="present-controls"><button class="secondary" data-action="prev-slide" aria-label="Previous slide">←</button><span id="slide-counter" class="micro" style="align-self:center;padding:0 10px">1 / 11</span><button class="secondary" data-action="next-slide" aria-label="Next slide">→</button><button class="secondary" data-action="exit-present">Exit</button></div></div>`;}
function updateLab(){const vals=Object.values(state.ratings).map(Number);const el=document.getElementById('lab-result');if(!el)return;el.textContent=vals.length<4?'No verdict yet. Complete all four checks after listening and testing a second phrase.':Math.min(...vals)<4?'Keep developing this candidate. Revisit the lowest-rated dimension, then compare again with the original take.':'Your own ratings support moving this candidate to a second listener review. This does not establish release readiness by itself.';}
function markdown(){const c=context();const slides=[...main.querySelectorAll('.slide')];const text='# ROYZ — Artist development brief\n\nGenerated '+new Date().toISOString()+'\n\nProvisional rules-based recommendations; no audio analyzed.\n\n'+slides.map(s=>'## '+s.querySelector('.slide-index').innerText.replace(/\n/g,' ')+'\n\n'+s.querySelector('.slide-inner').innerText).join('\n\n---\n\n')+'\n\n## Full answer record\n\n'+QUESTIONS.map(q=>'### '+q.prompt+'\n'+label(q.id)+(state.notes?.[q.id]?'\nYour note: '+state.notes[q.id]:'')).join('\n\n')+'\n\n## Sources\n\nhttps://help.suno.com/en/articles/11362369\nhttps://help.suno.com/en/articles/11362433\nhttps://help.suno.com/en/articles/9601665\nhttps://help.suno.com/en/articles/13614785\nhttps://help.suno.com/en/articles/13926209\n';download('ROYZ-development-brief.md',text,'text/markdown');}
function showSlide(i){const slides=[...main.querySelectorAll('.slide')];presentIndex=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>s.classList.toggle('current',j===presentIndex));document.getElementById('slide-counter').textContent=(presentIndex+1)+' / '+slides.length;window.scrollTo(0,0);}
function bind(){document.getElementById('answer-note')?.addEventListener('input',e=>{state.notes??={};state.notes[QUESTIONS[state.index].id]=e.target.value;persist();});for(const k of ['a','b']){const player=document.getElementById('player-'+k);if(player&&audioURLs[k]){player.src=audioURLs[k];document.getElementById('name-'+k).textContent=audioNames[k];}}main.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));main.querySelectorAll('[data-value]').forEach(b=>b.addEventListener('click',()=>{const q=QUESTIONS[state.index];if(q.type==='multi'){const old=Array.isArray(ans(q.id))?ans(q.id):[];state.answers[q.id]=old.includes(b.dataset.value)?old.filter(v=>v!==b.dataset.value):[...old,b.dataset.value];}else state.answers[q.id]=b.dataset.value;persist();const value=b.dataset.value;const y=window.scrollY;render();main.querySelector(`[data-value="${CSS.escape(value)}"]`)?.focus({preventScroll:true});window.scrollTo(0,y);}));main.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>chapter(Number(b.dataset.chapter))));document.getElementById('chapter-select')?.addEventListener('change',e=>chapter(Number(e.target.value)));main.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>go('quiz',QUESTIONS.findIndex(q=>q.id===b.dataset.edit))));document.getElementById('written-answer')?.addEventListener('input',e=>{state.answers[QUESTIONS[state.index].id]=e.target.value;persist();});main.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>{state.lens=b.dataset.lens;persist();render();main.querySelector('[data-lens="'+state.lens+'"]')?.focus({preventScroll:true});}));main.querySelectorAll('[data-rating]').forEach(s=>s.addEventListener('change',()=>{if(s.value)state.ratings[s.dataset.rating]=s.value;else delete state.ratings[s.dataset.rating];persist();updateLab();}));for(const k of ['a','b'])document.getElementById('audio-'+k)?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(f.size>100*1024*1024){toast('Choose a short audio file under 100 MB.');return;}if(audioURLs[k])URL.revokeObjectURL(audioURLs[k]);audioURLs[k]=URL.createObjectURL(f);audioNames[k]=f.name;state.ratings={};persist();main.querySelectorAll('[data-rating]').forEach(s=>s.value='');updateLab();const player=document.getElementById('player-'+k);player.src=audioURLs[k];player.onerror=()=>toast('This browser cannot play that audio. Try MP3, WAV or M4A.');document.getElementById('name-'+k).textContent=f.name;});}
function chapter(i){go('quiz',QUESTIONS.findIndex(q=>q.section===i));}
function action(a){if(a==='start')go('quiz',state.index);else if(a==='home')go('intro');else if(a==='back')state.index?go('quiz',state.index-1):go('intro');else if(a==='next'){if(state.index===QUESTIONS.length-1)go('review');else go('quiz',state.index+1);}else if(a==='unsure'){state.answers[QUESTIONS[state.index].id]='__unsure';persist();render();main.querySelector('[data-action="next"]')?.focus({preventScroll:true});}else if(a==='review')go('review');else if(a==='report')go('report');else if(a==='export')exportJSON();else if(a==='import')document.getElementById('import-file').click();else if(a==='markdown')markdown();else if(a==='print'){document.body.classList.remove('present');window.print();}else if(a==='reset'){if(confirm('Clear this session’s answers and voice ratings? Save a backup first if you want to keep them.')){state={version:VERSION,answers:{},notes:{},index:0,view:'intro',lens:'artist',ratings:{}};persist();render();window.scrollTo(0,0);}}else if(a==='present'){document.body.classList.add('present');showSlide(0);}else if(a==='exit-present')document.body.classList.remove('present');else if(a==='prev-slide')showSlide(presentIndex-1);else if(a==='next-slide')showSlide(presentIndex+1);}
document.querySelector('.logo').addEventListener('click',e=>{e.preventDefault();go('intro');});document.getElementById('export-top').addEventListener('click',exportJSON);
document.getElementById('import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Backup is too large. Choose a Royz answers JSON file under 2 MB.');const next=cleanState(JSON.parse(await f.text()));if(count()&&!confirm('Replace the current session with this backup?'))return;state=next;persist();render();toast('Session restored. Audio files must be reattached.');}catch(err){toast('Could not load backup: '+err.message);}finally{e.target.value='';}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(document.body.classList.contains('present')){if(e.key==='ArrowRight'){e.preventDefault();showSlide(presentIndex+1);}if(e.key==='ArrowLeft'){e.preventDefault();showSlide(presentIndex-1);}if(e.key==='Escape')document.body.classList.remove('present');return;}if(state.view==='quiz'&&['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key)&&document.activeElement.matches('[role=radio]')){e.preventDefault();const opts=[...main.querySelectorAll('[role=radio]')],idx=opts.indexOf(document.activeElement),next=(idx+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+opts.length)%opts.length;opts[next].click();}});
persist();render();
